class _Attributes(HTMLParser):
    """Collect (tag, attribute, value) with the stdlib tokenizer: quoted `>` and entities handled, script bodies skipped."""

    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.found = []

    def handle_starttag(self, tag, attrs):
        self.found += [(tag, name, value or '') for name, value in attrs]


def attributes(markup):
    parser = _Attributes()
    parser.feed(markup)
    parser.close()
    return parser.found


def duplicate_ids(page, label):
    """Every id in the final HTML, including ids inside author-supplied SVG, must be unique.

    A second `artifact-data` (or any repeated id) breaks getElementById, anchors, and `url(#…)`.
    """
    seen, errors = set(), []
    for _, name, value in attributes(page):
        if name != 'id':
            continue
        element_id = value.strip()
        if element_id in seen:
            errors.append(f'{label}: id {element_id!r} appears more than once; '
                          'rename ids inside svg blocks so they are unique across the page')
        seen.add(element_id)
    return errors


def render(exam):
    warnings = validate(exam)
    template = TEMPLATE.read_text(encoding='utf-8')
    worksheet = render_worksheet(exam, template)
    warnings += leak_check(worksheet, exam)
    key = render_key(exam, template)
    errors = duplicate_ids(worksheet, 'worksheet') + duplicate_ids(key, 'answer key')
    if errors:
        raise ExamError('\n'.join(dict.fromkeys(errors)))
    return worksheet, key, warnings


def main():
    parser = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    parser.add_argument('exam', type=Path)
    parser.add_argument('--out', type=Path, help='directory for the worksheet and key')
    parser.add_argument('--check', action='store_true', help='validate and render in memory without writing files')
    parser.add_argument('--force', action='store_true', help='replace existing output files')
    args = parser.parse_args()
    if not args.check and args.out is None:
        parser.error('give --out DIR, or --check to validate only')
    try:
        exam = json.loads(args.exam.read_text(encoding='utf-8-sig'))
        worksheet, key, warnings = render(exam)
        result = {'valid': True, 'questions': len(exam['questions']), 'warnings': warnings}
        if not args.check:
            args.out.mkdir(parents=True, exist_ok=True)
            paths = {'worksheet': args.out / worksheet_name(exam), 'key': args.out / key_name(exam)}
            existing = [str(p) for p in paths.values() if p.exists()]
            if existing and not args.force:
                raise ExamError(f'Refusing to replace {existing}. A changed paper needs a new artifact_version '
                                '(earlier versions stay beside it); use --force only to re-render the same version')
            paths['worksheet'].write_text(worksheet, encoding='utf-8')
            paths['key'].write_text(key, encoding='utf-8')
            result.update({k: str(v) for k, v in paths.items()})
        print(json.dumps(result, ensure_ascii=True, indent=2))
    except (OSError, ValueError, KeyError, TypeError, AttributeError) as error:
        parser.exit(1, f'Mock exam not rendered:\n{error}\n')


if __name__ == '__main__':
    main()
